#!/usr/bin/env python3
"""
Writes islamic_studio_quiz_batch2.sql: the second batch of Islamic Studio
quizzes (Bangla and English), on topics the first bank (islamic_studio_phase2.py,
quizbank_a … _d.py) covers thinly: how to pray, wudu and ghusl, fasting, zakat,
Hajj and Umrah, qurbani, janazah, Allah's names, the prophets, the companions,
the Mothers of the Believers, the seerah, the caliphate, Islam in Bengal, the
surahs, hadith terms, duas, manners and the Islamic months.

Each quiz: (slug, title, topic, difficulty, seconds or None, questions);
each question: (question, [four answers], index of the correct one, explanation, source).
Questions whose answer depends on the madhhab are left out on purpose; where the
schools differ only in status (fard / wajib / sunnah) the question asks about the
text of the hadith or ayah, not the ruling.

Quizzes go in as 'in_review' (the is_review_status enum has no 'pending'):
approve them in batools → Content Review. They are not added to any challenge.
Ids: uuid5 of 'batch2:<kind>:<key>', so they never collide with the first bank.
Re-runnable: fixed ids, ON CONFLICT DO NOTHING, nothing existing is overwritten.

    python3 islamic_studio_quiz_batch2.py
"""
import json
import uuid
from pathlib import Path

HERE = Path(__file__).resolve().parent
OUT = HERE / 'islamic_studio_quiz_batch2.sql'
NS = uuid.UUID('6f1c1b8e-6c2a-4d4e-9a57-1d2c3b4a5e60')
TOPICS = {'quran', 'prophets', 'pillars', 'seerah', 'history', 'fiqh', 'ramadan', 'general'}
REVIEW_STATUS = 'in_review'   # "waiting for the owner's approval"
FIRST_SORT_ORDER = 101        # after the first bank (1–38)


def sql(v) -> str:
    if v is None:
        return 'NULL'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, (int, float)):
        return str(v)
    if isinstance(v, (dict, list)):
        v = json.dumps(v, ensure_ascii=False)
    return "'" + str(v).replace("'", "''") + "'"


def uid(kind: str, key: str) -> str:
    return str(uuid.uuid5(NS, f'batch2:{kind}:{key}'))


def Q(en: str, bn: str) -> dict:
    return {'en': en, 'bn': bn}


