         [Q('Al-Jumu‘ah', 'আল-জুমুআ'), Q('Al-Baqarah', 'আল-বাকারা'), Q('Al-Ma’idah', 'আল-মায়িদা'), Q('Al-Hajj', 'আল-হজ')], 0,
