    ('batch2-mothers-of-believers', Q('Mothers of the Believers', 'উম্মুল মুমিনিন'), 'seerah', 'medium', None, [
        (Q('Which surah says "…and his wives are their mothers"?', 'কোন সূরায় আছে "…আর তাঁর স্ত্রীগণ তাদের মা"?'),
         [Q('An-Nisa', 'আন-নিসা'), Q('Al-Ahzab', 'আল-আহযাব'), Q('At-Tahrim', 'আত-তাহরিম'), Q('Maryam', 'মারইয়াম')], 1,
         Q('"The Prophet is closer to the believers than their own selves, and his wives are their mothers."', '"নবী মুমিনদের কাছে তাদের নিজেদের চেয়েও ঘনিষ্ঠ, আর তাঁর স্ত্রীগণ তাদের মা।"'), 'Quran 33:6'),
        (Q('Hafsah (RA), a Mother of the Believers, was the daughter of…?', 'উম্মুল মুমিনিন হাফসা (রা.) কার কন্যা?'),
         [Q('‘Umar ibn al-Khattab', 'উমর ইবনুল খাত্তাব (রা.)'), Q('Abu Bakr', 'আবু বকর (রা.)'), Q('Abu Sufyan', 'আবু সুফিয়ান (রা.)'), Q('‘Uthman', 'উসমান (রা.)')], 0,
         Q('Hafsah bint ‘Umar (RA) married the Prophet ﷺ after her first husband died.', 'হাফসা বিনতে উমর (রা.) প্রথম স্বামীর মৃত্যুর পর নবী ﷺ-এর সঙ্গে বিবাহবন্ধনে আবদ্ধ হন।'), 'Sahih al-Bukhari 4005'),
        (Q('After ‘Umar’s death, with whom were the pages of the Quran gathered by Abu Bakr kept?', 'উমর (রা.)-এর মৃত্যুর পর আবু বকর (রা.)-এর সংকলিত কুরআনের পাণ্ডুলিপি কার কাছে ছিল?'),
         [Q('‘A’ishah', 'আয়েশা (রা.)'), Q('Fatimah', 'ফাতিমা (রা.)'), Q('Hafsah', 'হাফসা (রা.)'), Q('Umm Salamah', 'উম্মে সালামা (রা.)')], 2,
         Q('The pages stayed with Abu Bakr, then ‘Umar, then Hafsah; ‘Uthman had copies made from them.', 'পাণ্ডুলিপি ছিল আবু বকর, তারপর উমর, তারপর হাফসা (রা.)-এর কাছে; উসমান (রা.) সেখান থেকে কপি করান।'), 'Sahih al-Bukhari 4986–4987'),
        (Q('Which Mother of the Believers gave her turn (day) to ‘A’ishah?', 'কোন উম্মুল মুমিনিন নিজের পালার দিন আয়েশা (রা.)-কে দিয়ে দিয়েছিলেন?'),
         [Q('Zaynab bint Jahsh', 'জয়নাব বিনতে জাহশ (রা.)'), Q('Safiyyah', 'সাফিয়্যা (রা.)'), Q('Juwayriyah', 'জুওয়াইরিয়া (রা.)'), Q('Sawdah bint Zam‘ah', 'সাওদা বিনতে জামআ (রা.)')], 3,
         Q('‘A’ishah (RA): "Sawdah gave her day to ‘A’ishah."', 'আয়েশা (রা.): "সাওদা (রা.) তাঁর দিনটি আয়েশাকে দিয়ে দিয়েছিলেন।"'), 'Sahih al-Bukhari 5212'),
        (Q('Whose marriage to the Prophet ﷺ is told in Surah al-Ahzab (33:37)?', 'সূরা আহযাবে (৩৩:৩৭) কার সঙ্গে নবী ﷺ-এর বিবাহের কথা আছে?'),
         [Q('Zaynab bint Jahsh', 'জয়নাব বিনতে জাহশ (রা.)'), Q('Khadijah', 'খাদিজা (রা.)'), Q('Maymunah', 'মাইমুনা (রা.)'), Q('Sawdah', 'সাওদা (রা.)')], 0,
         Q('Zaynab (RA) used to say to the other wives: "Allah married me to him from above the seven heavens."', 'জয়নাব (রা.) অন্য স্ত্রীদের বলতেন: "আল্লাহ সাত আসমানের ওপর থেকে আমার বিয়ে দিয়েছেন।"'), 'Quran 33:37; Sahih al-Bukhari 7420'),
        (Q('Which Mother of the Believers was the daughter of Abu Sufyan, married while she was in Abyssinia?', 'কোন উম্মুল মুমিনিন আবু সুফিয়ানের কন্যা, যাঁর বিয়ে হয়েছিল আবিসিনিয়ায় থাকা অবস্থায়?'),
         [Q('Hafsah', 'হাফসা (রা.)'), Q('Umm Habibah', 'উম্মে হাবিবা (রা.)'), Q('Umm Salamah', 'উম্মে সালামা (রা.)'), Q('‘A’ishah', 'আয়েশা (রা.)')], 1,
         Q('Umm Habibah (Ramlah) bint Abi Sufyan; the Negus arranged her marriage and gave her mahr.', 'উম্মে হাবিবা (রামলা) বিনতে আবি সুফিয়ান; নাজাশি তাঁর বিয়ের ব্যবস্থা করেন ও মোহর দেন।'), 'Sunan Abi Dawud 2107'),
        (Q('At Hudaybiyah, whose advice was "go out, sacrifice and shave, and the people will follow"?', 'হুদাইবিয়ায় কার পরামর্শ ছিল "আপনি বের হয়ে কুরবানি করুন ও মাথা মুণ্ডন করুন, মানুষ অনুসরণ করবে"?'),
         [Q('Sawdah', 'সাওদা (রা.)'), Q('Juwayriyah', 'জুওয়াইরিয়া (রা.)'), Q('Umm Salamah', 'উম্মে সালামা (রা.)'), Q('Safiyyah', 'সাফিয়্যা (রা.)')], 2,
         Q('He ﷺ did so, and the companions rushed to sacrifice and shave.', 'নবী ﷺ তা-ই করলেন, আর সাহাবিরা দ্রুত কুরবানি ও মাথা মুণ্ডন করলেন।'), 'Sahih al-Bukhari 2731'),
        (Q('Whose marriage to the Prophet ﷺ led the Muslims to free many captives of her tribe, Banu al-Mustaliq?', 'কার সঙ্গে নবী ﷺ-এর বিয়ের কারণে মুসলিমরা তাঁর গোত্র বনু মুস্তালিকের বহু বন্দিকে মুক্ত করে দেয়?'),
         [Q('Maymunah', 'মাইমুনা (রা.)'), Q('Zaynab bint Khuzaymah', 'জয়নাব বিনতে খুযাইমা (রা.)'), Q('Hafsah', 'হাফসা (রা.)'), Q('Juwayriyah bint al-Harith', 'জুওয়াইরিয়া বিনতে হারিস (রা.)')], 3,
         Q('‘A’ishah (RA): "I know of no woman more blessed for her people than her."', 'আয়েশা (রা.): "নিজের গোত্রের জন্য তাঁর চেয়ে বেশি বরকতময় কোনো নারীর কথা আমি জানি না।"'), 'Sunan Abi Dawud 3931'),
        (Q('Which Mother of the Believers was the daughter of Huyayy ibn Akhtab, married after Khaybar?', 'কোন উম্মুল মুমিনিন হুয়াই ইবনে আখতাবের কন্যা, খায়বারের পর যাঁর বিয়ে হয়?'),
         [Q('Safiyyah', 'সাফিয়্যা (রা.)'), Q('Sawdah', 'সাওদা (রা.)'), Q('Umm Habibah', 'উম্মে হাবিবা (রা.)'), Q('Zaynab bint Jahsh', 'জয়নাব বিনতে জাহশ (রা.)')], 0,
         Q('He ﷺ freed Safiyyah (RA) and made her freedom her mahr.', 'নবী ﷺ সাফিয়্যা (রা.)-কে মুক্ত করেন এবং মুক্তিকেই তাঁর মোহর বানান।'), 'Sahih al-Bukhari 4200'),
        (Q('The innocence of ‘A’ishah (RA) from the slander was revealed in which surah?', 'অপবাদ থেকে আয়েশা (রা.)-এর নির্দোষিতা কোন সূরায় নাজিল হয়?'),
         [Q('Al-Ahzab', 'আল-আহযাব'), Q('An-Nur', 'আন-নূর'), Q('Al-Hujurat', 'আল-হুজুরাত'), Q('Al-Mujadilah', 'আল-মুজাদালা')], 1,
         Q('"Indeed, those who came with the slander are a group among you…" — ten ayahs of an-Nur.', '"নিশ্চয় যারা এই অপবাদ রটনা করেছে তারা তোমাদেরই একটি দল…" — সূরা নূরের দশ আয়াত।'), 'Quran 24:11–20; Sahih al-Bukhari 4750'),
    ]),
