    ('batch2-seerah-makkah', Q('Seerah: the Makkan years', 'সীরাত: মক্কী জীবন'), 'seerah', 'medium', None, [
        (Q('On which hill did the Prophet ﷺ first openly call the clans of Quraysh?', 'নবী ﷺ কোন পাহাড়ে উঠে প্রথম প্রকাশ্যে কুরাইশ গোত্রগুলোকে ডেকেছিলেন?'),
         [Q('Uhud', 'উহুদ'), Q('Thawr', 'সাওর'), Q('As-Safa', 'সাফা'), Q('Arafat', 'আরাফাত')], 2,
         Q('When "Warn your nearest kin" was revealed, he ﷺ climbed as-Safa and called out to the clans.', '"আপনার নিকটাত্মীয়দের সতর্ক করুন" নাজিল হলে নবী ﷺ সাফায় উঠে গোত্রগুলোকে ডাকলেন।'), 'Quran 26:214; Sahih al-Bukhari 4770'),
        (Q('In whose house did the early Muslims meet in secret to learn Islam?', 'প্রথম যুগের মুসলিমরা গোপনে কার বাড়িতে মিলিত হয়ে ইসলাম শিখতেন?'),
         [Q('Al-Arqam ibn Abi al-Arqam (Dar al-Arqam)', 'আরকাম ইবনে আবিল আরকাম (দারুল আরকাম)'), Q('Abu Jahl', 'আবু জাহল'), Q('Abu Lahab', 'আবু লাহাব'), Q('Waraqah', 'ওয়ারাকা')], 0,
         Q('Dar al-Arqam near as-Safa was the first centre of teaching Islam in Makkah.', 'সাফার কাছে দারুল আরকাম ছিল মক্কায় ইসলাম শিক্ষার প্রথম কেন্দ্র।'), 'Sirah Ibn Hisham; Ibn Sa‘d, at-Tabaqat'),
        (Q('To which land did the first Muslims emigrate to escape persecution?', 'নির্যাতন থেকে বাঁচতে প্রথম মুসলিমরা কোন দেশে হিজরত করেন?'),
         [Q('Yemen', 'ইয়েমেন'), Q('Abyssinia (Habashah)', 'আবিসিনিয়া (হাবশা)'), Q('Persia', 'পারস্য'), Q('Egypt', 'মিসর')], 1,
         Q('The Prophet ﷺ sent them to Abyssinia, whose king wronged no one.', 'নবী ﷺ তাঁদের আবিসিনিয়ায় পাঠান, যার বাদশাহ কারো ওপর জুলুম করতেন না।'), 'Musnad Ahmad 1740; Sirah Ibn Hisham'),
        (Q('What was the title of the just king of Abyssinia who protected the Muslims?', 'মুসলিমদের আশ্রয়দাতা আবিসিনিয়ার ন্যায়পরায়ণ বাদশাহর উপাধি কী?'),
         [Q('Kisra', 'কিসরা'), Q('Qaysar', 'কায়সার'), Q('Fir‘awn', 'ফেরাউন'), Q('An-Najashi (the Negus)', 'নাজাশি')], 3,
         Q('When the Negus died, the Prophet ﷺ prayed the funeral prayer for him in Madinah.', 'নাজাশির মৃত্যুর পর নবী ﷺ মদিনায় তাঁর গায়েবানা জানাযা পড়েন।'), 'Sahih al-Bukhari 1333'),
        (Q('For about how long were Banu Hashim boycotted in the valley of Abu Talib?', 'আবু তালিব উপত্যকায় বনু হাশিমকে প্রায় কত দিন বয়কট করে রাখা হয়েছিল?'),
         [Q('Three months', 'তিন মাস'), Q('Ten years', 'দশ বছর'), Q('About three years', 'প্রায় তিন বছর'), Q('Forty days', 'চল্লিশ দিন')], 2,
         Q('Quraysh signed a pact to boycott them; it lasted about three years before it collapsed.', 'কুরাইশরা বয়কটের চুক্তি করে; প্রায় তিন বছর পর তা ভেঙে যায়।'), 'Sirah Ibn Hisham'),
        (Q('In which cave did the Prophet ﷺ and Abu Bakr hide during the Hijrah?', 'হিজরতের সময় নবী ﷺ ও আবু বকর (রা.) কোন গুহায় আত্মগোপন করেছিলেন?'),
         [Q('Hira', 'হেরা'), Q('Thawr', 'সাওর'), Q('Uhud', 'উহুদ'), Q('Al-Kahf', 'আল-কাহফ')], 1,
         Q('They stayed three nights in a cave in Mount Thawr.', 'তাঁরা সাওর পাহাড়ের একটি গুহায় তিন রাত ছিলেন।'), 'Sahih al-Bukhari 3905'),
        (Q('Who slept in the Prophet’s ﷺ bed on the night of the Hijrah?', 'হিজরতের রাতে কে নবী ﷺ-এর বিছানায় শুয়েছিলেন?'),
         [Q('‘Ali ibn Abi Talib', 'আলী ইবনে আবি তালিব (রা.)'), Q('Zayd ibn Harithah', 'যায়েদ ইবনে হারিসা (রা.)'), Q('Bilal', 'বিলাল (রা.)'), Q('‘Uthman', 'উসমান (রা.)')], 0,
         Q('‘Ali (RA) stayed behind, slept in his bed and returned the trusts people had left with the Prophet ﷺ.', 'আলী (রা.) থেকে গেলেন, নবীজির বিছানায় ঘুমালেন এবং মানুষের আমানত ফেরত দিলেন।'), 'Sirah Ibn Hisham; Musnad Ahmad (from Ibn ‘Abbas)'),
        (Q('Where did the people of Yathrib (Madinah) pledge allegiance to the Prophet ﷺ before the Hijrah?', 'হিজরতের আগে ইয়াসরিবের (মদিনার) লোকেরা কোথায় নবী ﷺ-এর হাতে বায়আত গ্রহণ করে?'),
         [Q('Badr', 'বদর'), Q('Ta’if', 'তায়েফ'), Q('Hudaybiyah', 'হুদাইবিয়া'), Q('Al-‘Aqabah', 'আকাবা')], 3,
         Q('‘Ubadah ibn as-Samit (RA) was among those who gave the pledge on the night of al-‘Aqabah.', 'উবাদা ইবনে সামিত (রা.) আকাবার রাতে বায়আতকারীদের একজন ছিলেন।'), 'Sahih al-Bukhari 3892–3893'),
        (Q('For how many years did the Prophet ﷺ stay in Makkah after the revelation began?', 'ওহি শুরুর পর নবী ﷺ মক্কায় কত বছর ছিলেন?'),
         [Q('5', '৫'), Q('10', '১০'), Q('13', '১৩'), Q('23', '২৩')], 2,
         Q('Ibn ‘Abbas (RA): he stayed thirteen years in Makkah receiving revelation, then emigrated and lived ten years in Madinah.', 'ইবনে আব্বাস (রা.): তিনি ওহি পেয়ে মক্কায় তেরো বছর ছিলেন, তারপর হিজরত করে মদিনায় দশ বছর ছিলেন।'), 'Sahih al-Bukhari 3902'),
        (Q('When the people of Makkah asked for a sign, what happened to the moon?', 'মক্কাবাসী নিদর্শন চাইলে চাঁদের কী হয়েছিল?'),
         [Q('It split in two', 'দুই টুকরা হয়েছিল'), Q('It turned red', 'লাল হয়ে গিয়েছিল'), Q('It vanished for a month', 'এক মাস অদৃশ্য ছিল'), Q('It rose in the west', 'পশ্চিমে উদিত হয়েছিল')], 0,
         Q('"The Hour has drawn near and the moon has split."', '"কিয়ামত নিকটবর্তী হয়েছে এবং চাঁদ দ্বিখণ্ডিত হয়েছে।"'), 'Quran 54:1; Sahih al-Bukhari 3868'),
    ]),
    ('batch2-seerah-madinah', Q('Seerah: the Madinan years', 'সীরাত: মাদানী জীবন'), 'seerah', 'hard', 600, [
        (Q('The bond the Prophet ﷺ made between the Muhajirun and the Ansar is called…?', 'মুহাজির ও আনসারদের মধ্যে নবী ﷺ যে বন্ধন স্থাপন করেন তাকে কী বলে?'),
         [Q('Al-Mu’akhah (brotherhood)', 'মুআখাত (ভ্রাতৃত্ব)'), Q('Al-Hijrah', 'হিজরত'), Q('Al-Bay‘ah', 'বায়আত'), Q('As-Sulh', 'সন্ধি')], 0,
         Q('Each emigrant was made the brother of an Ansari, like ‘Abd ar-Rahman ibn ‘Awf and Sa‘d ibn ar-Rabi‘.', 'প্রত্যেক মুহাজিরকে একজন আনসারির ভাই বানানো হয়, যেমন আবদুর রহমান ইবনে আউফ ও সাদ ইবনুর রাবি।'), 'Sahih al-Bukhari 2048'),
        (Q('About how long after the Hijrah did the qiblah change to the Ka‘bah?', 'হিজরতের প্রায় কত দিন পর কিবলা কাবার দিকে পরিবর্তিত হয়?'),
         [Q('One week', 'এক সপ্তাহ'), Q('Five years', 'পাঁচ বছর'), Q('Sixteen or seventeen months', 'ষোলো বা সতেরো মাস'), Q('Ten years', 'দশ বছর')], 2,
         Q('Al-Bara’ (RA): he prayed toward Bayt al-Maqdis for sixteen or seventeen months, then the qiblah was turned.', 'বারা (রা.): নবী ﷺ ষোলো বা সতেরো মাস বায়তুল মাকদিসের দিকে নামাজ পড়েন, তারপর কিবলা পরিবর্তিত হয়।'), 'Sahih al-Bukhari 40; Quran 2:144'),
        (Q('About how many Muslims fought at Badr?', 'বদরের যুদ্ধে প্রায় কতজন মুসলিম ছিলেন?'),
         [Q('About 70', 'প্রায় ৭০'), Q('About 313', 'প্রায় ৩১৩'), Q('About 1,000', 'প্রায় ১,০০০'), Q('About 3,000', 'প্রায় ৩,০০০')], 1,
         Q('Al-Bara’ (RA): they were three hundred and ten-odd, like the number who crossed the river with Talut.', 'বারা (রা.): তাঁরা ছিলেন তিনশো দশের কিছু বেশি, তালুতের সঙ্গে নদী পার হওয়া লোকদের সমান।'), 'Sahih al-Bukhari 3957'),
        (Q('Who led the people in prayer during the Prophet’s ﷺ final illness?', 'নবী ﷺ-এর শেষ অসুস্থতার সময় কে নামাজে ইমামতি করেছিলেন?'),
         [Q('‘Umar', 'উমর (রা.)'), Q('‘Ali', 'আলী (রা.)'), Q('Bilal', 'বিলাল (রা.)'), Q('Abu Bakr', 'আবু বকর (রা.)')], 3,
         Q('"Tell Abu Bakr to lead the people in prayer."', '"আবু বকরকে বলো, সে যেন মানুষের নামাজে ইমামতি করে।"'), 'Sahih al-Bukhari 664'),
        (Q('Which was the last military expedition the Prophet ﷺ went out on?', 'নবী ﷺ সর্বশেষ কোন অভিযানে নিজে বের হয়েছিলেন?'),
         [Q('Tabuk', 'তাবুক'), Q('Badr', 'বদর'), Q('Khaybar', 'খায়বার'), Q('Uhud', 'উহুদ')], 0,
         Q('Ka‘b ibn Malik (RA): "I never stayed behind the Messenger ﷺ in any expedition except Tabuk," his last, in 9 AH.', 'কাব ইবনে মালিক (রা.): "তাবুক ছাড়া কোনো অভিযানে আমি পিছিয়ে থাকিনি" — এটি ছিল ৯ হিজরির শেষ অভিযান।'), 'Sahih al-Bukhari 4418'),
        (Q('In which battle, soon after the conquest of Makkah, did the Muslims’ large numbers at first make them proud?', 'মক্কা বিজয়ের পরপর কোন যুদ্ধে মুসলিমরা প্রথমে নিজেদের সংখ্যাধিক্যে গর্বিত হয়েছিল?'),
         [Q('Badr', 'বদর'), Q('Mu’tah', 'মুতা'), Q('Hunayn', 'হুনাইন'), Q('The Trench', 'খন্দক')], 2,
         Q('"…and on the day of Hunayn, when your great number pleased you, but it did not help you at all."', '"…আর হুনাইনের দিন, যখন তোমাদের সংখ্যাধিক্য তোমাদের মুগ্ধ করেছিল, কিন্তু তা তোমাদের কোনো কাজে আসেনি।"'), 'Quran 9:25'),
        (Q('In which year was Khaybar conquered?', 'খায়বার কোন সালে বিজিত হয়?'),
         [Q('2 AH', '২ হিজরি'), Q('7 AH', '৭ হিজরি'), Q('5 AH', '৫ হিজরি'), Q('10 AH', '১০ হিজরি')], 1,
         Q('Khaybar was taken in 7 AH, after the Treaty of Hudaybiyah (6 AH).', 'হুদাইবিয়ার সন্ধির (৬ হিজরি) পর ৭ হিজরিতে খায়বার বিজয় হয়।'), 'Sahih al-Bukhari 4197; Sirah Ibn Hisham'),
        (Q('The year 9 AH, when tribes from all over Arabia came to accept Islam, is called…?', '৯ হিজরি সাল, যখন আরবের নানা গোত্র এসে ইসলাম গ্রহণ করে, তাকে কী বলে?'),
         [Q('The Year of Sorrow', 'দুঃখের বছর'), Q('The Year of the Elephant', 'হাতির বছর'), Q('The Year of Victory', 'বিজয়ের বছর'), Q('The Year of Delegations (‘Am al-Wufud)', 'প্রতিনিধিদলের বছর (আমুল উফুদ)')], 3,
         Q('After Makkah was conquered, delegations came one after another; Surah an-Nasr describes people entering Islam in crowds.', 'মক্কা বিজয়ের পর একের পর এক প্রতিনিধিদল আসে; সূরা নাসরে দলে দলে ইসলামে প্রবেশের কথা আছে।'), 'Quran 110:2; Sirah Ibn Hisham'),
        (Q('At what age did the Prophet ﷺ pass away?', 'নবী ﷺ কত বছর বয়সে ইন্তেকাল করেন?'),
         [Q('63', '৬৩'), Q('60', '৬০'), Q('70', '৭০'), Q('53', '৫৩')], 0,
         Q('‘A’ishah (RA): he passed away at the age of sixty-three.', 'আয়েশা (রা.): তিনি তেষট্টি বছর বয়সে ইন্তেকাল করেন।'), 'Sahih al-Bukhari 3536'),
        (Q('What was the name of the Prophet’s ﷺ she-camel, which he rode in the Farewell Hajj?', 'বিদায় হজে নবী ﷺ যে উটনীতে আরোহণ করেছিলেন, তার নাম কী?'),
         [Q('Al-Buraq', 'বুরাক'), Q('Al-Qaswa’', 'কাসওয়া'), Q('Duldul', 'দুলদুল'), Q('The she-camel of Salih', 'সালেহ (আ.)-এর উটনী')], 1,
         Q('Jabir (RA) describes him riding al-Qaswa’ at Dhul-Hulayfah and at Arafah.', 'জাবির (রা.) বর্ণনা করেন, তিনি যুলহুলাইফা ও আরাফায় কাসওয়ায় আরোহণ করেছিলেন।'), 'Sahih Muslim 1218'),
    ]),
