    ('batch2-khilafah', Q('The Rightly Guided Caliphate', 'খোলাফায়ে রাশেদিন'), 'history', 'medium', None, [
        (Q('The Prophet ﷺ said the caliphate (in the way of prophethood) would last…?', 'নবী ﷺ বলেছেন, (নবুয়তের আদর্শে) খিলাফত কত বছর থাকবে?'),
         [Q('10 years', '১০ বছর'), Q('100 years', '১০০ বছর'), Q('30 years', '৩০ বছর'), Q('12 years', '১২ বছর')], 2,
         Q('"The caliphate in my ummah will be thirty years," — roughly the time of the four rightly guided caliphs (with al-Hasan).', '"আমার উম্মতের মধ্যে খিলাফত থাকবে ত্রিশ বছর" — মোটামুটি চার খলিফার (হাসান (রা.)-সহ) সময়কাল।'), 'Sunan Abi Dawud 4646; Jami‘ at-Tirmidhi 2226'),
        (Q('Which caliph fought those who refused to pay zakat after the Prophet ﷺ died?', 'নবী ﷺ-এর ইন্তেকালের পর যাকাত দিতে অস্বীকারকারীদের বিরুদ্ধে কোন খলিফা লড়াই করেন?'),
         [Q('Abu Bakr', 'আবু বকর (রা.)'), Q('‘Umar', 'উমর (রা.)'), Q('‘Uthman', 'উসমান (রা.)'), Q('‘Ali', 'আলী (রা.)')], 0,
         Q('Abu Bakr (RA): "By Allah, I will fight whoever separates salah from zakat."', 'আবু বকর (রা.): "আল্লাহর কসম, যে নামাজ ও যাকাতের মধ্যে পার্থক্য করবে, আমি তার বিরুদ্ধে লড়ব।"'), 'Sahih al-Bukhari 1400'),
        (Q('Which caliph started dating years by the Hijri calendar?', 'কোন খলিফা হিজরি সাল গণনা চালু করেন?'),
         [Q('Abu Bakr', 'আবু বকর (রা.)'), Q('‘Ali', 'আলী (রা.)'), Q('Mu‘awiyah', 'মুআবিয়া (রা.)'), Q('‘Umar', 'উমর (রা.)')], 3,
         Q('In ‘Umar’s caliphate the companions agreed to count the years from the Hijrah.', 'উমর (রা.)-এর খিলাফতকালে সাহাবিরা হিজরত থেকে সাল গণনায় একমত হন।'), 'Tarikh at-Tabari; Sahih al-Bukhari 3934'),
        (Q('In whose caliphate did Jerusalem come under Muslim rule, the caliph himself coming to receive it?', 'কার খিলাফতকালে জেরুজালেম মুসলিমদের অধীনে আসে, খলিফা নিজে এসে তা গ্রহণ করেন?'),
         [Q('Abu Bakr', 'আবু বকর (রা.)'), Q('‘Umar', 'উমর (রা.)'), Q('‘Uthman', 'উসমান (রা.)'), Q('‘Ali', 'আলী (রা.)')], 1,
         Q('‘Umar (RA) travelled to Jerusalem (about 637–638 CE) and gave its people a covenant of safety.', 'উমর (রা.) জেরুজালেমে গিয়ে (প্রায় ৬৩৭–৬৩৮ খ্রি.) সেখানকার মানুষকে নিরাপত্তার অঙ্গীকারনামা দেন।'), 'Tarikh at-Tabari'),
        (Q('The great battle against the Byzantine army in Syria in 636 CE was at…?', '৬৩৬ খ্রিস্টাব্দে সিরিয়ায় বাইজেন্টাইন বাহিনীর বিরুদ্ধে মহাযুদ্ধ কোথায় হয়?'),
         [Q('Al-Yarmuk', 'ইয়ারমুক'), Q('Badr', 'বদর'), Q('Nahawand', 'নাহাওয়ান্দ'), Q('Hunayn', 'হুনাইন')], 0,
         Q('At al-Yarmuk the Muslims, with Khalid ibn al-Walid among the commanders, defeated the Byzantines.', 'ইয়ারমুকে খালিদ ইবনুল ওয়ালিদ (রা.)-সহ মুসলিম সেনাপতিরা বাইজেন্টাইনদের পরাজিত করেন।'), 'Tarikh at-Tabari; al-Bidayah wan-Nihayah'),
        (Q('Who commanded the Muslims at al-Qadisiyyah against the Persian army?', 'কাদিসিয়ায় পারস্য বাহিনীর বিরুদ্ধে মুসলিমদের সেনাপতি কে ছিলেন?'),
         [Q('Khalid ibn al-Walid', 'খালিদ ইবনুল ওয়ালিদ (রা.)'), Q('‘Amr ibn al-‘As', 'আমর ইবনুল আস (রা.)'), Q('Sa‘d ibn Abi Waqqas', 'সাদ ইবনে আবি ওয়াক্কাস (রা.)'), Q('Abu Hurayrah', 'আবু হুরায়রা (রা.)')], 2,
         Q('Sent by ‘Umar (RA), Sa‘d defeated the Persians at al-Qadisiyyah and later entered al-Mada’in.', 'উমর (রা.)-এর পাঠানো সাদ (রা.) কাদিসিয়ায় পারসিকদের পরাজিত করেন এবং পরে মাদায়েনে প্রবেশ করেন।'), 'Tarikh at-Tabari'),
        (Q('Which caliph was martyred in his house while reading the Quran?', 'কোন খলিফা নিজ গৃহে কুরআন পাঠরত অবস্থায় শহিদ হন?'),
         [Q('Abu Bakr', 'আবু বকর (রা.)'), Q('‘Umar', 'উমর (রা.)'), Q('‘Ali', 'আলী (রা.)'), Q('‘Uthman', 'উসমান (রা.)')], 3,
         Q('‘Uthman (RA) was besieged by rebels and martyred in 35 AH, his mushaf open before him.', 'উসমান (রা.) বিদ্রোহীদের দ্বারা অবরুদ্ধ হয়ে ৩৫ হিজরিতে শহিদ হন, তখন তাঁর সামনে মুসহাফ খোলা ছিল।'), 'Tarikh at-Tabari; al-Bidayah wan-Nihayah'),
        (Q('Which caliph made Kufa his capital?', 'কোন খলিফা কুফাকে রাজধানী করেন?'),
         [Q('‘Ali', 'আলী (রা.)'), Q('‘Umar', 'উমর (রা.)'), Q('Abu Bakr', 'আবু বকর (রা.)'), Q('‘Uthman', 'উসমান (রা.)')], 0,
         Q('‘Ali (RA) moved from Madinah to Kufa in Iraq.', 'আলী (রা.) মদিনা থেকে ইরাকের কুফায় রাজধানী সরিয়ে নেন।'), 'Tarikh at-Tabari'),
        (Q('About how long was Abu Bakr’s caliphate?', 'আবু বকর (রা.)-এর খিলাফতকাল প্রায় কত দিন?'),
         [Q('Ten years', 'দশ বছর'), Q('About two years', 'প্রায় দুই বছর'), Q('Six months', 'ছয় মাস'), Q('Twelve years', 'বারো বছর')], 1,
         Q('From 11 AH to his death in 13 AH: about two years and three months.', '১১ হিজরি থেকে ১৩ হিজরিতে তাঁর ইন্তেকাল পর্যন্ত: প্রায় দুই বছর তিন মাস।'), 'Tarikh at-Tabari'),
        (Q('Which caliph was stabbed while leading the Fajr prayer?', 'কোন খলিফা ফজরের নামাজে ইমামতি করার সময় ছুরিকাহত হন?'),
         [Q('‘Uthman', 'উসমান (রা.)'), Q('Abu Bakr', 'আবু বকর (রা.)'), Q('‘Umar', 'উমর (রা.)'), Q('Mu‘awiyah', 'মুআবিয়া (রা.)')], 2,
         Q('‘Umar (RA) was stabbed by Abu Lu’lu’ah while beginning the Fajr prayer and died days later (23 AH).', 'উমর (রা.) ফজরের নামাজ শুরু করার সময় আবু লুলুর ছুরিকাঘাতে আহত হন এবং কিছুদিন পর (২৩ হিজরি) শহিদ হন।'), 'Sahih al-Bukhari 3700'),
    ]),
    ('batch2-islam-in-bengal-2', Q('Islam in Bengal — part 2', 'বাংলায় ইসলাম — পর্ব ২'), 'history', 'medium', None, [
        (Q('The shrine of Hazrat Shah Makhdum Rupos is in…?', 'হযরত শাহ মখদুম রূপোশ (রহ.)-এর মাজার কোথায়?'),
         [Q('Rajshahi', 'রাজশাহী'), Q('Sylhet', 'সিলেট'), Q('Chattogram', 'চট্টগ্রাম'), Q('Khulna', 'খুলনা')], 0,
         Q('Shah Makhdum is remembered for spreading Islam in the Rajshahi region.', 'শাহ মখদুম (রহ.) রাজশাহী অঞ্চলে ইসলাম প্রচারের জন্য স্মরণীয়।'), 'Banglapedia: Shah Makhdum Rupos'),
        (Q('Which sultan united Bengal and was called "Shah-i-Bangalah"?', 'কোন সুলতান বাংলাকে ঐক্যবদ্ধ করে "শাহ-ই-বাঙ্গালাহ" উপাধি পান?'),
         [Q('Alauddin Husain Shah', 'আলাউদ্দিন হোসেন শাহ'), Q('Shamsuddin Ilyas Shah', 'শামসুদ্দিন ইলিয়াস শাহ'), Q('Bakhtiyar Khalji', 'বখতিয়ার খলজি'), Q('Isa Khan', 'ঈসা খাঁ')], 1,
         Q('Ilyas Shah united the regions of Bengal around 1352 CE and founded the Ilyas Shahi dynasty.', 'ইলিয়াস শাহ প্রায় ১৩৫২ খ্রিস্টাব্দে বাংলার অঞ্চলগুলোকে ঐক্যবদ্ধ করে ইলিয়াস শাহি বংশ প্রতিষ্ঠা করেন।'), 'Banglapedia: Ilyas Shah'),
        (Q('The Choto Sona Mosque (Small Golden Mosque) is in which district?', 'ছোট সোনা মসজিদ কোন জেলায়?'),
         [Q('Bagerhat', 'বাগেরহাট'), Q('Dhaka', 'ঢাকা'), Q('Chapainawabganj', 'চাঁপাইনবাবগঞ্জ'), Q('Cumilla', 'কুমিল্লা')], 2,
         Q('It stands at Shibganj in Chapainawabganj, in the old Gaur area, from the time of Sultan Husain Shah.', 'এটি চাঁপাইনবাবগঞ্জের শিবগঞ্জে, প্রাচীন গৌড় এলাকায়, সুলতান হোসেন শাহের আমলের।'), 'Banglapedia: Chhota Sona Mosque'),
        (Q('Which Bengal sultan built the huge Adina Mosque at Pandua?', 'পান্ডুয়ার বিশাল আদিনা মসজিদ কোন সুলতান নির্মাণ করেন?'),
         [Q('Sikandar Shah', 'সিকান্দার শাহ'), Q('Ghiyasuddin Azam Shah', 'গিয়াসউদ্দিন আজম শাহ'), Q('Shaista Khan', 'শায়েস্তা খান'), Q('Khan Jahan Ali', 'খান জাহান আলী')], 0,
         Q('Sultan Sikandar Shah, son of Ilyas Shah, built it in the 1370s; it was among the largest mosques of the subcontinent.', 'ইলিয়াস শাহের পুত্র সুলতান সিকান্দার শাহ ১৩৭০-এর দশকে এটি নির্মাণ করেন; এটি উপমহাদেশের বৃহত্তম মসজিদগুলোর একটি ছিল।'), 'Banglapedia: Adina Mosque'),
        (Q('Who wrote the beloved Eid song "O mon Ramzaner oi rozar sheshe elo khushir Eid"?', '"ও মন রমজানের ওই রোজার শেষে এলো খুশির ঈদ" গানটি কে লিখেছেন?'),
         [Q('Rabindranath Tagore', 'রবীন্দ্রনাথ ঠাকুর'), Q('Jasimuddin', 'জসীমউদ্দীন'), Q('Farrukh Ahmad', 'ফররুখ আহমদ'), Q('Kazi Nazrul Islam', 'কাজী নজরুল ইসলাম')], 3,
         Q('National poet Kazi Nazrul Islam wrote it, and Abbasuddin Ahmed first sang it; it is one of his many Islamic songs.', 'জাতীয় কবি কাজী নজরুল ইসলাম এটি লেখেন, প্রথম গেয়েছিলেন আব্বাসউদ্দীন আহমদ; এটি তাঁর অসংখ্য ইসলামি গানের একটি।'), 'Banglapedia: Kazi Nazrul Islam'),
        (Q('"Bishad Sindhu", the Bangla classic about the tragedy of Karbala, was written by…?', 'কারবালার বিয়োগান্ত ঘটনা নিয়ে বাংলা ধ্রুপদি গ্রন্থ "বিষাদ সিন্ধু" কে লিখেছেন?'),
         [Q('Kazi Nazrul Islam', 'কাজী নজরুল ইসলাম'), Q('Mir Mosharraf Hossain', 'মীর মশাররফ হোসেন'), Q('Begum Rokeya', 'বেগম রোকেয়া'), Q('Ismail Hossain Siraji', 'ইসমাইল হোসেন সিরাজী')], 1,
         Q('Mir Mosharraf Hossain published Bishad Sindhu in parts from 1885.', 'মীর মশাররফ হোসেন ১৮৮৫ সাল থেকে খণ্ডে খণ্ডে বিষাদ সিন্ধু প্রকাশ করেন।'), 'Banglapedia: Mir Mosharraf Hossain'),
        (Q('Which saint, said to be a nephew of Shah Jalal, also has his shrine in Sylhet?', 'শাহজালাল (রহ.)-এর ভাগ্নে হিসেবে পরিচিত কোন সাধকের মাজারও সিলেটে?'),
         [Q('Khan Jahan Ali', 'খান জাহান আলী'), Q('Shah Makhdum', 'শাহ মখদুম'), Q('Shah Paran', 'শাহ পরান'), Q('Shah Ali Baghdadi', 'শাহ আলী বাগদাদি')], 2,
         Q('Shah Paran’s shrine is at Khadim Nagar on the edge of Sylhet city.', 'শাহ পরান (রহ.)-এর মাজার সিলেট শহরের প্রান্তে খাদিমনগরে।'), 'Banglapedia: Shah Paran'),
        (Q('The Kusumba Mosque, a Sultanate-era stone mosque shown on the five-taka note, is in…?', 'পাঁচ টাকার নোটে ছাপা সুলতানি আমলের পাথরের কুসুম্বা মসজিদ কোথায়?'),
         [Q('Bagerhat', 'বাগেরহাট'), Q('Sonargaon', 'সোনারগাঁও'), Q('Old Dhaka', 'পুরান ঢাকা'), Q('Naogaon', 'নওগাঁ')], 3,
         Q('It was built in 1558–59 at Manda, Naogaon, during the Afghan Sultanate.', 'এটি ১৫৫৮–৫৯ সালে আফগান সুলতানি আমলে নওগাঁর মান্দায় নির্মিত।'), 'Banglapedia: Kusumba Mosque'),
        (Q('Which sultan of Bengal (1494–1519) is remembered for supporting Bangla literature?', 'বাংলার কোন সুলতান (১৪৯৪–১৫১৯) বাংলা সাহিত্যের পৃষ্ঠপোষকতার জন্য স্মরণীয়?'),
         [Q('Alauddin Husain Shah', 'আলাউদ্দিন হোসেন শাহ'), Q('Sikandar Shah', 'সিকান্দার শাহ'), Q('Murshid Quli Khan', 'মুর্শিদ কুলি খান'), Q('Siraj ud-Daulah', 'সিরাজউদ্দৌলা')], 0,
         Q('Husain Shah’s reign is called a golden age of Bengal; poets wrote in Bangla under his patronage.', 'হোসেন শাহের শাসনকালকে বাংলার স্বর্ণযুগ বলা হয়; তাঁর পৃষ্ঠপোষকতায় কবিরা বাংলায় লিখতেন।'), 'Banglapedia: Husain Shah'),
        (Q('Sonargaon, an old capital of Bengal, is in which district today?', 'বাংলার প্রাচীন রাজধানী সোনারগাঁও বর্তমানে কোন জেলায়?'),
         [Q('Gazipur', 'গাজীপুর'), Q('Narayanganj', 'নারায়ণগঞ্জ'), Q('Munshiganj', 'মুন্সিগঞ্জ'), Q('Narsingdi', 'নরসিংদী')], 1,
         Q('Sonargaon was the seat of Fakhruddin Mubarak Shah and a great centre of trade and learning.', 'সোনারগাঁও ছিল ফখরুদ্দিন মুবারক শাহের রাজধানী এবং বাণিজ্য ও শিক্ষার বড় কেন্দ্র।'), 'Banglapedia: Sonargaon'),
    ]),
