    ('batch2-everyday-duas', Q('Everyday duas', 'প্রতিদিনের দোয়া'), 'general', 'easy', None, [
        (Q('What does the bedtime dua "Bismika Allahumma amutu wa ahya" mean?', 'ঘুমানোর দোয়া "বিসমিকা আল্লাহুম্মা আমুতু ওয়া আহইয়া" অর্থ কী?'),
         [Q('In Your name, O Allah, I die and I live', 'হে আল্লাহ, আপনার নামেই আমি মরি ও বাঁচি'), Q('O Allah, give me good sleep', 'হে আল্লাহ, আমাকে ভালো ঘুম দিন'),
          Q('O Allah, forgive my parents', 'হে আল্লাহ, আমার বাবা-মাকে ক্ষমা করুন'), Q('All praise is for Allah', 'সব প্রশংসা আল্লাহর')], 0,
         Q('He ﷺ said it when going to bed; sleep is called a kind of death.', 'নবী ﷺ শোয়ার সময় এটি বলতেন; ঘুমকে এক প্রকার মৃত্যু বলা হয়েছে।'), 'Sahih al-Bukhari 6324'),
        (Q('When is "Alhamdu lillahil-ladhi ahyana ba‘da ma amatana wa ilayhin-nushur" said?', '"আলহামদু লিল্লাহিল্লাযি আহইয়ানা বা‘দা মা আমাতানা ওয়া ইলাইহিন নুশুর" কখন পড়া হয়?'),
         [Q('Before eating', 'খাওয়ার আগে'), Q('On entering the masjid', 'মসজিদে প্রবেশের সময়'), Q('On waking up', 'ঘুম থেকে জেগে'), Q('When it rains', 'বৃষ্টির সময়')], 2,
         Q('"All praise is for Allah who gave us life after He caused us to die, and to Him is the return."', '"সব প্রশংসা আল্লাহর, যিনি আমাদের মৃত্যুর পর জীবন দিলেন, আর তাঁর কাছেই ফিরে যেতে হবে।"'), 'Sahih al-Bukhari 6324'),
        (Q('What does the dua for entering the masjid, "Allahummaftah li abwaba rahmatik", mean?', 'মসজিদে প্রবেশের দোয়া "আল্লাহুম্মাফতাহ লি আবওয়াবা রাহমাতিক" অর্থ কী?'),
         [Q('O Allah, I ask You of Your bounty', 'হে আল্লাহ, আমি আপনার অনুগ্রহ চাই'), Q('O Allah, open for me the doors of Your mercy', 'হে আল্লাহ, আমার জন্য আপনার রহমতের দরজাগুলো খুলে দিন'),
          Q('O Allah, protect me from Satan', 'হে আল্লাহ, শয়তান থেকে রক্ষা করুন'), Q('O Allah, increase my knowledge', 'হে আল্লাহ, আমার জ্ঞান বাড়িয়ে দিন')], 1,
         Q('"When one of you enters the masjid, let him say: O Allah, open for me the doors of Your mercy."', '"তোমাদের কেউ মসজিদে প্রবেশ করলে বলবে: হে আল্লাহ, আমার জন্য আপনার রহমতের দরজাগুলো খুলে দিন।"'), 'Sahih Muslim 713'),
        (Q('And on leaving the masjid, he ﷺ taught us to say…?', 'আর মসজিদ থেকে বের হওয়ার সময় নবী ﷺ কী বলতে শিখিয়েছেন?'),
         [Q('Allahumma inni as’aluka min fadlik', 'আল্লাহুম্মা ইন্নি আসআলুকা মিন ফাদলিক'), Q('Bismillahi tawakkaltu ‘alallah', 'বিসমিল্লাহি তাওয়াক্কালতু আলাল্লাহ'),
          Q('Subhanaka Allahumma', 'সুবহানাকা আল্লাহুম্মা'), Q('Inna lillahi wa inna ilayhi raji‘un', 'ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন')], 0,
         Q('"…and when he leaves, let him say: O Allah, I ask You of Your bounty."', '"…আর বের হওয়ার সময় বলবে: হে আল্লাহ, আমি আপনার কাছে আপনার অনুগ্রহ প্রার্থনা করি।"'), 'Sahih Muslim 713'),
        (Q('If you forget to say Bismillah at the start of a meal, what do you say when you remember?', 'খাওয়ার শুরুতে বিসমিল্লাহ বলতে ভুলে গেলে মনে পড়লে কী বলবেন?'),
         [Q('Alhamdulillah', 'আলহামদুলিল্লাহ'), Q('Nothing', 'কিছুই না'), Q('Astaghfirullah', 'আসতাগফিরুল্লাহ'), Q('Bismillahi awwalahu wa akhirahu', 'বিসমিল্লাহি আউয়ালাহু ওয়া আখিরাহু')], 3,
         Q('"…let him say: In the name of Allah, at its beginning and its end."', '"…সে যেন বলে: বিসমিল্লাহি আউয়ালাহু ওয়া আখিরাহু — শুরুতে ও শেষে আল্লাহর নামে।"'), 'Sunan Abi Dawud 3767; Jami‘ at-Tirmidhi 1858'),
        (Q('What does the Quranic dua for parents, "Rabbir-hamhuma kama rabbayani saghira", mean?', 'বাবা-মায়ের জন্য কুরআনের দোয়া "রাব্বির হামহুমা কামা রাব্বায়ানি সাগিরা" অর্থ কী?'),
         [Q('My Lord, give them wealth', 'হে আমার রব, তাঁদের সম্পদ দিন'), Q('My Lord, forgive me', 'হে আমার রব, আমাকে ক্ষমা করুন'),
          Q('My Lord, have mercy on them as they raised me when I was small', 'হে আমার রব, তাঁদের প্রতি দয়া করুন, যেমন তাঁরা শৈশবে আমাকে লালন-পালন করেছেন'), Q('My Lord, give them long life', 'হে আমার রব, তাঁদের দীর্ঘ জীবন দিন')], 2,
         Q('Al-Isra’ 17:24, right after the command to be good to parents.', 'আল-ইসরা ১৭:২৪, বাবা-মায়ের সঙ্গে সদ্ব্যবহারের আদেশের ঠিক পরে।'), 'Quran 17:24'),
        (Q('"Rabbana atina fid-dunya hasanah…" asks Allah for good in…?', '"রাব্বানা আতিনা ফিদ দুনিয়া হাসানাহ…" দোয়ায় কী চাওয়া হয়?'),
         [Q('This world only', 'শুধু দুনিয়ার কল্যাণ'), Q('This world and the Hereafter, and safety from the Fire', 'দুনিয়া ও আখিরাতের কল্যাণ এবং জাহান্নাম থেকে মুক্তি'),
          Q('Rain', 'বৃষ্টি'), Q('Victory in battle', 'যুদ্ধে বিজয়')], 1,
         Q('"Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire."', '"হে আমাদের রব, আমাদের দুনিয়াতে কল্যাণ দিন, আখিরাতে কল্যাণ দিন এবং আগুনের শাস্তি থেকে রক্ষা করুন।"'), 'Quran 2:201'),
        (Q('What does "Rabbi zidni ‘ilma" mean?', '"রাব্বি জিদনি ইলমা" অর্থ কী?'),
         [Q('My Lord, increase me in knowledge', 'হে আমার রব, আমার জ্ঞান বৃদ্ধি করুন'), Q('My Lord, increase my wealth', 'হে আমার রব, আমার সম্পদ বাড়িয়ে দিন'),
          Q('My Lord, make me patient', 'হে আমার রব, আমাকে ধৈর্যশীল করুন'), Q('My Lord, guide my children', 'হে আমার রব, আমার সন্তানদের হেদায়াত দিন')], 0,
         Q('"…and say: My Lord, increase me in knowledge."', '"…এবং বলুন: হে আমার রব, আমার জ্ঞান বৃদ্ধি করুন।"'), 'Quran 20:114'),
        (Q('Which words did the Prophet ﷺ say when setting off on a journey on his mount?', 'বাহনে চড়ে সফরে রওনা হওয়ার সময় নবী ﷺ কোন বাক্য পড়তেন?'),
         [Q('Inna lillahi wa inna ilayhi raji‘un', 'ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন'), Q('Rabbighfir li', 'রাব্বিগফিরলি'),
          Q('Labbayk Allahumma labbayk', 'লাব্বাইক আল্লাহুম্মা লাব্বাইক'), Q('Subhanalladhi sakhkhara lana hadha…', 'সুবহানাল্লাযি সাখখারা লানা হাযা…')], 3,
         Q('"Glory be to Him who has subjected this to us, and we could not have done it ourselves; and to our Lord we will return."', '"পবিত্র তিনি, যিনি এটিকে আমাদের বশীভূত করেছেন, অথচ আমরা একে বশ করতে সক্ষম ছিলাম না; আর আমরা আমাদের রবের দিকেই ফিরে যাব।"'), 'Quran 43:13–14; Sahih Muslim 1342'),
        (Q('At iftar the Prophet ﷺ said "Dhahabadh-dhama’ wabtallatil-‘uruq…". What does it mean?', 'ইফতারের সময় নবী ﷺ বলতেন "যাহাবায যামাউ ওয়াবতাল্লাতিল উরুক…"। এর অর্থ কী?'),
         [Q('I intend to fast tomorrow', 'আমি আগামীকাল রোজার নিয়ত করছি'), Q('O Allah, accept my prayer', 'হে আল্লাহ, আমার নামাজ কবুল করুন'),
          Q('The thirst has gone, the veins are moistened, and the reward is certain, if Allah wills', 'পিপাসা দূর হলো, শিরাগুলো সিক্ত হলো, আর ইনশাআল্লাহ সওয়াব নিশ্চিত হলো'), Q('Glory be to Allah, the Great', 'মহান আল্লাহ পবিত্র')], 2,
         Q('Ibn ‘Umar (RA) reported he said this when breaking his fast.', 'ইবনে উমর (রা.) বর্ণনা করেন, নবী ﷺ ইফতারের সময় এটি বলতেন।'), 'Sunan Abi Dawud 2357'),
    ]),
    ('batch2-adab-akhlaq', Q('Manners of a Muslim', 'মুসলিমের আদব-আখলাক'), 'general', 'easy', None, [
        (Q('Who should give the salam first: the one riding or the one walking?', 'কে আগে সালাম দেবে: আরোহী নাকি পথচারী?'),
         [Q('The one walking', 'পথচারী'), Q('The one riding', 'আরোহী'), Q('Whoever is older', 'যে বয়সে বড়'), Q('Neither', 'কেউ না')], 1,
         Q('"The rider greets the walker, the walker greets the one sitting, and the few greet the many."', '"আরোহী পথচারীকে, পথচারী বসা ব্যক্তিকে এবং অল্পসংখ্যক অধিকসংখ্যককে সালাম দেবে।"'), 'Sahih al-Bukhari 6232'),
        (Q('Between a young person and an older one, who greets first?', 'ছোট ও বড়র মধ্যে কে আগে সালাম দেবে?'),
         [Q('The older one', 'বড়জন'), Q('Whoever is richer', 'যে বেশি ধনী'), Q('The younger one', 'ছোটজন'), Q('Whoever is taller', 'যে বেশি লম্বা')], 2,
         Q('"The young greet the old, the passer-by greets the one sitting, and the few greet the many."', '"ছোট বড়কে, পথচারী বসা ব্যক্তিকে এবং অল্পসংখ্যক অধিকসংখ্যককে সালাম দেবে।"'), 'Sahih al-Bukhari 6231'),
        (Q('How many times should you ask permission to enter, before leaving if there is no answer?', 'প্রবেশের অনুমতি কতবার চাইবেন, উত্তর না পেলে ফিরে যাওয়ার আগে?'),
         [Q('Once', 'একবার'), Q('Ten times', 'দশবার'), Q('Until the door opens', 'দরজা খোলা পর্যন্ত'), Q('Three times', 'তিনবার')], 3,
         Q('"If one of you asks permission three times and is not given it, let him go back."', '"তোমাদের কেউ তিনবার অনুমতি চেয়ে অনুমতি না পেলে সে যেন ফিরে যায়।"'), 'Sahih al-Bukhari 6245'),
        (Q('"Whoever believes in Allah and the Last Day, let him speak good or…"', '"যে আল্লাহ ও শেষ দিবসে বিশ্বাস করে, সে যেন ভালো কথা বলে অথবা…"'),
         [Q('…keep silent', '…চুপ থাকে'), Q('…speak loudly', '…জোরে বলে'), Q('…leave the gathering', '…মজলিস ছেড়ে চলে যায়'), Q('…write it down', '…লিখে রাখে')], 0,
         Q('Speak good, or stay silent.', 'ভালো কথা বলো, নয়তো চুপ থাকো।'), 'Sahih al-Bukhari 6018'),
        (Q('"A Muslim is one from whose tongue and hand…"', '"প্রকৃত মুসলিম সে, যার জিহ্বা ও হাত থেকে…"'),
         [Q('…charity flows', '…দান প্রবাহিত হয়'), Q('…other Muslims are safe', '…অন্য মুসলিমরা নিরাপদ থাকে'), Q('…no word comes out', '…কোনো কথা বের হয় না'), Q('…the Quran is heard', '…কুরআন শোনা যায়')], 1,
         Q('"The Muslim is the one from whose tongue and hand the Muslims are safe."', '"মুসলিম সে, যার জিহ্বা ও হাত থেকে অন্য মুসলিমরা নিরাপদ।"'), 'Sahih al-Bukhari 10'),
        (Q('A man asked the Prophet ﷺ for advice again and again. What did he keep saying?', 'এক ব্যক্তি বারবার উপদেশ চাইলে নবী ﷺ বারবার কী বলেছিলেন?'),
         [Q('Pray more', 'বেশি নামাজ পড়ো'), Q('Fast often', 'বেশি রোজা রাখো'), Q('Do not become angry', 'রাগ কোরো না'), Q('Travel', 'সফর করো')], 2,
         Q('He ﷺ repeated: "Do not become angry."', 'নবী ﷺ বারবার বললেন: "রাগ কোরো না।"'), 'Sahih al-Bukhari 6116'),
        (Q('The Prophet ﷺ said: "The religion is…"', 'নবী ﷺ বলেছেন: "দ্বীন হলো…"'),
         [Q('…sincere good will (nasihah)', '…কল্যাণকামিতা (নসিহত)'), Q('…hardship', '…কঠোরতা'), Q('…for scholars only', '…শুধু আলেমদের জন্য'), Q('…rituals only', '…শুধু আনুষ্ঠানিকতা')], 0,
         Q('"The religion is nasihah" — to Allah, His Book, His Messenger, the leaders of the Muslims and their common people.', '"দ্বীন হলো নসিহত (কল্যাণকামিতা)" — আল্লাহ, তাঁর কিতাব, তাঁর রাসুল, মুসলিম নেতৃবৃন্দ ও সাধারণ মুসলিমদের জন্য।'), 'Sahih Muslim 55'),
        (Q('Signs of a hypocrite: when he speaks he lies, when he promises he breaks it, and when he is trusted he…?', 'মুনাফিকের আলামত: কথা বললে মিথ্যা বলে, ওয়াদা করলে ভঙ্গ করে, আর আমানত রাখলে…?'),
         [Q('Returns it', 'ফেরত দেয়'), Q('Forgets', 'ভুলে যায়'), Q('Prays', 'নামাজ পড়ে'), Q('Betrays the trust', 'খেয়ানত করে')], 3,
         Q('"The signs of a hypocrite are three: when he speaks he lies, when he promises he breaks it, and when he is trusted he betrays."', '"মুনাফিকের আলামত তিনটি: কথা বললে মিথ্যা বলে, ওয়াদা করলে ভঙ্গ করে, আমানত রাখলে খেয়ানত করে।"'), 'Sahih al-Bukhari 33'),
        (Q('What did the Prophet ﷺ forbid while drinking?', 'পান করার সময় নবী ﷺ কী নিষেধ করেছেন?'),
         [Q('Saying Bismillah', 'বিসমিল্লাহ বলা'), Q('Breathing into the vessel', 'পাত্রের মধ্যে নিঃশ্বাস ফেলা'), Q('Using the right hand', 'ডান হাত ব্যবহার করা'), Q('Drinking water', 'পানি পান করা')], 1,
         Q('"When one of you drinks, let him not breathe into the vessel."', '"তোমাদের কেউ পান করার সময় যেন পাত্রে নিঃশ্বাস না ফেলে।"'), 'Sahih al-Bukhari 5630'),
        (Q('Besides mocking others, Surah al-Hujurat 49:11 also forbids…?', 'অন্যকে উপহাস করা ছাড়াও সূরা হুজুরাত ৪৯:১১ আর কী নিষেধ করে?'),
         [Q('Calling one another by offensive nicknames', 'একে অপরকে মন্দ নামে ডাকা'), Q('Greeting strangers', 'অপরিচিতকে সালাম দেওয়া'), Q('Visiting the sick', 'রোগী দেখতে যাওয়া'), Q('Smiling', 'হাসিমুখে থাকা')], 0,
         Q('"…and do not insult one another, and do not call each other by (offensive) nicknames."', '"…তোমরা একে অপরের নিন্দা কোরো না এবং একে অপরকে মন্দ নামে ডেকো না।"'), 'Quran 49:11'),
    ]),
