        (Q('Which is the third month of the Hijri year?', 'হিজরি বছরের তৃতীয় মাস কোনটি?'),
         [Q('Safar', 'সফর'), Q('Jumada al-Ula', 'জমাদিউল আউয়াল'), Q('Rabi‘ ath-Thani', 'রবিউস সানি'), Q('Rabi‘ al-Awwal', 'রবিউল আউয়াল')], 3,
         Q('Muharram, Safar, Rabi‘ al-Awwal, Rabi‘ ath-Thani, Jumada al-Ula, Jumada al-Akhirah, Rajab, Sha‘ban, Ramadan, Shawwal, Dhul Qa‘dah, Dhul Hijjah.', 'মহররম, সফর, রবিউল আউয়াল, রবিউস সানি, জমাদিউল আউয়াল, জমাদিউস সানি, রজব, শাবান, রমজান, শাওয়াল, জিলকদ, জিলহজ।'), 'The Hijri calendar'),
        (Q('Which is the twelfth and last month of the Hijri year?', 'হিজরি বছরের দ্বাদশ ও শেষ মাস কোনটি?'),
         [Q('Dhul Hijjah', 'জিলহজ'), Q('Dhul Qa‘dah', 'জিলকদ'), Q('Shawwal', 'শাওয়াল'), Q('Muharram', 'মহররম')], 0,
         Q('Dhul Hijjah, the month of Hajj, ends the year; Muharram begins the next.', 'হজের মাস জিলহজ দিয়ে বছর শেষ হয়; পরের বছর শুরু হয় মহররম দিয়ে।'), 'The Hijri calendar'),
