# The first bank's slugs, so a batch-2 slug never repeats one (the ids differ anyway).
FIRST_BANK = ['quran-basics', 'prophets', 'pillars-and-salah', 'seerah', 'ramadan', 'islamic-history']


def first_bank_questions() -> set[str]:
    """English question texts of the first bank (to catch a repeated question)."""
    import sys
    sys.path.insert(0, str(HERE))
    try:
        from quizbank_a import QUIZZES as A
        from quizbank_b import QUIZZES as B
        from quizbank_c import QUIZZES as C
        from quizbank_d import QUIZZES as D
    except ImportError:
        return set()
    FIRST_BANK.extend(q[0] for q in A + B + C + D)
    return {norm(question['en']) for q in A + B + C + D for question, *_ in q[5]}


def norm(text: str) -> str:
    return ''.join(ch for ch in text.lower() if ch.isalnum())


def check(quizzes):
    old_questions = first_bank_questions()
    slugs = [q[0] for q in quizzes]
    assert len(slugs) == len(set(slugs)), 'duplicate quiz slug'
    assert not set(slugs) & set(FIRST_BANK), 'slug used by the first bank'
    seen = set()
    for slug, title, topic, level, seconds, questions in quizzes:
        assert slug.startswith('batch2-'), slug
        assert topic in TOPICS, (slug, topic)
        assert level in ('easy', 'medium', 'hard'), (slug, level)
        assert len(questions) == 10, (slug, len(questions))
        for n, (question, answers, correct, explanation, source) in enumerate(questions, 1):
            assert len(answers) == 4 and 0 <= correct < 4, (slug, n)
            for text in [question, explanation, title, *answers]:
                assert set(text) == {'en', 'bn'} and text['en'].strip() and text['bn'].strip(), (slug, n)
            assert len({a['en'] for a in answers}) == 4 and len({a['bn'] for a in answers}) == 4, (slug, n, 'repeated answer')
            assert source and source.strip(), (slug, n, 'no source')
            key = norm(question['en'])
            assert key not in seen, (slug, n, 'question repeated in batch 2')
            assert key not in old_questions, (slug, n, 'question already in the first bank')
            seen.add(key)


def build(quizzes) -> str:
    total = sum(len(q[5]) for q in quizzes)
    out = [f"""-- Islamic Studio quiz bank, batch 2: {len(quizzes)} quizzes, {total} questions (English and Bangla).
-- Generated by islamic_studio_quiz_batch2.py; edit that, not this.
-- Run after migration 077 (any time after islamic_studio_quizbank.sql). Safe to run again:
-- fixed ids, ON CONFLICT DO NOTHING, nothing existing is changed.
-- The quizzes go in as '{REVIEW_STATUS}' (waiting for approval): the app shows them only after
-- approval in batools → Islamic Studio → Content Review. They are not added to any challenge.

BEGIN;
"""]
    for order, (slug, title, topic, level, seconds, questions) in enumerate(quizzes, FIRST_SORT_ORDER):
        qid = uid('quiz', slug)
        out.append(f'\n-- {title["en"]} / {title["bn"]}')
        out.append(
            'INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('
            f"{sql(qid)}, {sql(title)}, {sql(topic)}, {sql(level)}, {sql(seconds)}, 10, {sql(REVIEW_STATUS)}, {order}) ON CONFLICT (id) DO NOTHING;")
        for n, (question, answers, correct, explanation, source) in enumerate(questions, 1):
            question_id = uid('question', f'{slug}:{n}')
            out.append(
                'INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('
                f"{sql(question_id)}, {sql(qid)}, {sql(question)}, {sql(explanation)}, {sql(source)}, {n}) ON CONFLICT (id) DO NOTHING;")
            values = ', '.join(
                f"({sql(uid('option', f'{slug}:{n}:{k}'))}, {sql(question_id)}, {sql(a)}, {sql(k == correct)}, {k + 1})"
                for k, a in enumerate(answers))
            out.append(f'INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES {values} ON CONFLICT (id) DO NOTHING;')
    ids = ', '.join(sql(uid('quiz', q[0])) + '::uuid' for q in quizzes)
    out.append(f"""
COMMIT;

SELECT 'batch 2 quizzes' AS what, count(*) FROM is_quizzes WHERE id IN ({ids})
UNION ALL SELECT 'batch 2 questions', count(*) FROM is_quiz_questions WHERE quiz_id IN ({ids})
UNION ALL SELECT 'batch 2 quizzes waiting for review', count(*) FROM is_quizzes WHERE id IN ({ids}) AND review_status = '{REVIEW_STATUS}';
""")
    return '\n'.join(out)


if __name__ == '__main__':
    check(QUIZZES)
    OUT.write_text(build(QUIZZES))
    levels = {lv: sum(1 for q in QUIZZES if q[3] == lv) for lv in ('easy', 'medium', 'hard')}
    print(f'✔ {OUT.name}: {len(QUIZZES)} quizzes, {sum(len(q[5]) for q in QUIZZES)} questions, '
          f'{sum(len(q[5]) for q in QUIZZES) * 4} answers ({levels}; {OUT.stat().st_size // 1024} KB)')
